function normalizeParams(params) {
  return (params || []).map(function (value) {
    if (value === undefined) return null;
    if (typeof value === 'boolean') return value ? 1 : 0;
    return value;
  });
}

async function openDb(env) {
  const d1 = env && env.DB;
  if (d1 && typeof d1.prepare === 'function') {
    return {
      driver: 'd1',
      query: async function (sql, params) {
        const statement = d1.prepare(sql);
        const result = await statement.bind(...normalizeParams(params)).all();
        return (result && result.results) || [];
      },
      run: async function (sql, params) {
        const statement = d1.prepare(sql);
        return statement.bind(...normalizeParams(params)).run();
      },
      exec: async function (sql) { return d1.exec(sql); }
    };
  }

  // node:sqlite —— 本地与 Node 运行时使用，惰性导入，避免在无该模块的运行时启动即崩
  const { DatabaseSync } = await import('node:sqlite');
  const path = (env && (env.SQLITE_PATH || env.BAMBOO_DB_PATH)) || DEFAULT_DB_PATH;
  if (path !== ':memory:') {
    const dir = path.replace(/[\\/][^\\/]*$/, '');
    if (dir && dir !== path) {
      const fs = await import('node:fs/promises');
      await fs.mkdir(dir, { recursive: true });
    }
  }
  const handle = new DatabaseSync(path);
  handle.exec('PRAGMA journal_mode = WAL;');
  handle.exec('PRAGMA foreign_keys = ON;');
  return {
    driver: 'sqlite',
    path: path,
    query: async function (sql, params) { return handle.prepare(sql).all(...normalizeParams(params)); },
    run: async function (sql, params) { return handle.prepare(sql).run(...normalizeParams(params)); },
    exec: async function (sql) { return handle.exec(sql); },
    close: function () { handle.close(); }
  };
}

let dbReady = null;

async function getDb(env) {
  if (!dbReady) {
    dbReady = (async function () {
      const db = await openDb(env);
      await db.exec(SCHEMA_SQL);
      await ensureCoverColumn(db);
      await ensurePriceCurrencyColumn(db);
      await seedIfEmpty(db);
      await ensurePricesColumn(db);
      await ensureShippingIncluded(db);
      await ensureOrderLifecycle(db);
      await seedMediaCovers(db);
      await ensureAdmin(db, env);
      return db;
    })();
    dbReady.catch(function () { dbReady = null; });
  }
  return dbReady;
}

async function countRows(db, table) {
  const rows = await db.query('SELECT COUNT(*) AS total FROM ' + table);
  return rows.length ? Number(rows[0].total) || 0 : 0;
}

async function ensureCoverColumn(db) {
  try {
    await db.exec('ALTER TABLE products ADD COLUMN cover_image TEXT');
  } catch (error) {
    const message = error && error.message ? String(error.message) : '';
    if (!/duplicate column|already exists/i.test(message)) throw error;
  }
}

async function ensurePriceCurrencyColumn(db) {
  try {
    await db.exec("ALTER TABLE products ADD COLUMN price_currency TEXT NOT NULL DEFAULT 'USD'");
  } catch (error) {
    const message = error && error.message ? String(error.message) : '';
    if (!/duplicate column|already exists/i.test(message)) throw error;
  }
}

/** 多语言多币种价格列：老库补列，并把基础价按汇率回填成四档，保证升级后前台立刻有价可显示 */
async function ensureShippingIncluded(db) {
  // 商品价格已含运费：把历史订单里单列的运费并入合计（total = subtotal）
  try {
    await db.run('UPDATE orders SET total = subtotal, shipping = 0 WHERE shipping > 0', []);
  } catch (error) {
    /* 老库没有 shipping 列时忽略 */
  }
}

async function ensureOrderLifecycle(db) {
  // 订单状态拆成「支付状态 + 发货状态」两维：老库补列并按旧 status 回填
  const addColumn = async function (sql) {
    try { await db.run(sql); } catch (error) { /* 列已存在 */ }
  };
  await addColumn("ALTER TABLE orders ADD COLUMN shipping_status TEXT NOT NULL DEFAULT 'pending'");
  await addColumn('ALTER TABLE orders ADD COLUMN tracking_no TEXT');
  try {
    await db.run("UPDATE orders SET shipping_status = 'shipped' WHERE status = 'shipped' AND shipping_status = 'pending'");
    await db.run("UPDATE orders SET shipping_status = 'delivered' WHERE status = 'delivered' AND shipping_status = 'pending'");
    await db.run("UPDATE orders SET payment_status = 'paid' WHERE payment_status IN ('demo', 'pending') AND status IN ('processing', 'paid', 'shipped', 'delivered')");
    await db.run("UPDATE orders SET payment_status = 'unpaid' WHERE payment_status IN ('demo', 'pending') AND status IN ('pending_payment', 'cancelled')");
  } catch (error) {
    /* 老库缺列时忽略 */
  }
}

/* 支付 / 发货两维状态推导出综合状态，保留旧的 status 列供列表与统计兼容 */
function deriveOrderStatus(paymentStatus, shippingStatus) {
  if (paymentStatus === 'refunded') return 'cancelled';
  if (paymentStatus !== 'paid') return 'pending_payment';
  if (shippingStatus === 'delivered') return 'delivered';
  if (shippingStatus === 'shipped') return 'shipped';
  return 'processing';
}

async function ensurePricesColumn(db) {
  try {
    await db.exec("ALTER TABLE products ADD COLUMN prices_json TEXT NOT NULL DEFAULT '{}'");
  } catch (error) {
    const message = error && error.message ? String(error.message) : '';
    if (!/duplicate column|already exists/i.test(message)) throw error;
  }
  const rows = await db.query("SELECT id, price, price_currency, prices_json FROM products WHERE prices_json IS NULL OR prices_json = '' OR prices_json = '{}'");
  for (const row of rows) {
    const base = Number(row.price);
    if (!Number.isFinite(base) || base <= 0) continue;
    const currency = findCurrency(row.price_currency).code;
    const prices = {};
    PRICE_LOCALES.forEach(function (locale) {
      const target = PRICE_LOCALE_CURRENCY[locale];
      prices[locale] = { currency: target, amount: roundMoney(convertAmount(base, currency, target), target) };
    });
    await db.run('UPDATE products SET prices_json = ? WHERE id = ?', [JSON.stringify(prices), row.id]);
  }
}

const COVER_SEED_VERSION = 'v2';

async function seedMediaCovers(db) {
  const entries = Object.keys(COVER_SEED_BASE64 || {});
  for (const productId of entries) {
    const id = 'seed-' + COVER_SEED_VERSION + '-' + productId;
    const existing = await db.query('SELECT id FROM media WHERE id = ?', [id]);
    if (!existing.length) {
      await db.run('INSERT INTO media (id, content_type, data_b64, bytes, created_at) VALUES (?, ?, ?, ?, ?)', [
        id, 'image/jpeg', COVER_SEED_BASE64[productId], Math.floor(COVER_SEED_BASE64[productId].length * 3 / 4), new Date().toISOString()
      ]);
    }
    await db.run('UPDATE products SET cover_image = ? WHERE id = ? AND (cover_image IS NULL OR cover_image = ? OR cover_image LIKE ?)', ['/media/' + id, productId, '', '/media/seed-%']);
  }
  await db.run('DELETE FROM media WHERE id LIKE ? AND id NOT LIKE ?', ['seed-%', 'seed-' + COVER_SEED_VERSION + '-%']);
}

async function seedIfEmpty(db) {
  if (await countRows(db, 'products') > 0) return;
  const seeds = buildSeedProducts();
  for (const product of seeds) {
    await insertProduct(db, product);
  }
  console.log('[db] seeded ' + seeds.length + ' products');
}

/* ------------------------------------------------------------------ *
 * 口令与会话（PBKDF2-SHA256 + 随机 token，token 只存哈希）
 * ------------------------------------------------------------------ */
function bytesToBase64Url(bytes) {
  let binary = '';
  new Uint8Array(bytes).forEach(function (byte) { binary += String.fromCharCode(byte); });
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function base64UrlToBytes(value) {
  const normalized = String(value).replace(/-/g, '+').replace(/_/g, '/');
  const padded = normalized + '='.repeat((4 - (normalized.length % 4)) % 4);
  const binary = atob(padded);
  return Uint8Array.from(binary, function (char) { return char.charCodeAt(0); });
}

async function sha256Hex(value) {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(value));
  return Array.from(new Uint8Array(digest)).map(function (byte) { return byte.toString(16).padStart(2, '0'); }).join('');
}

async function derivePasswordHash(password, salt, iterations) {
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(String(password)), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', salt: salt, iterations: iterations, hash: 'SHA-256' }, key, 256);
  return new Uint8Array(bits);
}

async function hashPassword(password) {
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const hash = await derivePasswordHash(password, salt, PBKDF2_ITERATIONS);
  return 'pbkdf2$' + PBKDF2_ITERATIONS + '$' + bytesToBase64Url(salt) + '$' + bytesToBase64Url(hash);
}

function constantTimeEqual(a, b) {
  const left = String(a);
  const right = String(b);
  if (left.length !== right.length) return false;
  let diff = 0;
  for (let i = 0; i < left.length; i += 1) diff |= left.charCodeAt(i) ^ right.charCodeAt(i);
  return diff === 0;
}

async function verifyPassword(password, stored) {
  const parts = String(stored || '').split('$');
  if (parts.length !== 4 || parts[0] !== 'pbkdf2') return false;
  const iterations = Number(parts[1]);
  if (!Number.isFinite(iterations) || iterations <= 0) return false;
  let salt;
  try { salt = base64UrlToBytes(parts[2]); } catch (_) { return false; }
  const hash = await derivePasswordHash(password, salt, iterations);
  return constantTimeEqual(bytesToBase64Url(hash), parts[3]);
}

async function ensureAdmin(db, env) {
  const email = String((env && env.ADMIN_EMAIL) || '').trim().toLowerCase();
  const password = String((env && env.ADMIN_PASSWORD) || '');
  if (!email || !password) return;
  const name = String((env && env.ADMIN_NAME) || '管理员');
  const rows = await db.query('SELECT id, password_hash FROM admin_users WHERE email = ?', [email]);
  if (!rows.length) {
    await db.run('INSERT INTO admin_users (email, name, password_hash, created_at) VALUES (?, ?, ?, ?)', [email, name, await hashPassword(password), new Date().toISOString()]);
    console.log('[db] admin account created for ' + email);
    return;
  }
  if (!await verifyPassword(password, rows[0].password_hash)) {
    await db.run('UPDATE admin_users SET password_hash = ?, updated_at = ? WHERE id = ?', [await hashPassword(password), new Date().toISOString(), rows[0].id]);
    await db.run('DELETE FROM admin_sessions WHERE admin_id = ?', [rows[0].id]);
    console.log('[db] admin password rotated from environment for ' + email);
  }
}

async function createSession(db, adminId) {
  const token = bytesToBase64Url(crypto.getRandomValues(new Uint8Array(32)));
  const now = Date.now();
  await db.run('INSERT INTO admin_sessions (token_hash, admin_id, created_at, expires_at) VALUES (?, ?, ?, ?)', [
    await sha256Hex(token), adminId, new Date(now).toISOString(), new Date(now + SESSION_TTL_MS).toISOString()
  ]);
  return token;
}

/* ---------- 商城会员：邮箱 + 密码 ---------- */
function normalizeEmail(value) {
  return String(value || '').trim().toLowerCase();
}

function validEmail(email) {
  return email.length >= 5 && email.length <= 160 && /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email);
}

async function createCustomerSession(db, customerId) {
  const token = bytesToBase64Url(crypto.getRandomValues(new Uint8Array(32)));
  const now = Date.now();
  await db.run('INSERT INTO customer_sessions (token_hash, customer_id, created_at, expires_at) VALUES (?, ?, ?, ?)', [
    await sha256Hex(token), customerId, new Date(now).toISOString(), new Date(now + SESSION_TTL_MS).toISOString()
  ]);
  return token;
}

async function customerFromRequest(request, db) {
  const token = request.headers.get('x-customer-token');
  if (!token) return null;
  const tokenHash = await sha256Hex(String(token));
  const rows = await db.query('SELECT c.id, c.email, c.name, s.expires_at FROM customer_sessions s JOIN customers c ON c.id = s.customer_id WHERE s.token_hash = ?', [tokenHash]);
  if (!rows.length) return null;
  if (Date.parse(rows[0].expires_at) <= Date.now()) {
    await db.run('DELETE FROM customer_sessions WHERE token_hash = ?', [tokenHash]);
    return null;
  }
  return { id: rows[0].id, email: rows[0].email, name: rows[0].name || '' };
}

async function adminAllowed(request, db) {
  const token = request.headers.get('x-admin-token');
  if (!token) return false;
  const rows = await db.query('SELECT token_hash, expires_at FROM admin_sessions WHERE token_hash = ?', [await sha256Hex(String(token))]);
  if (!rows.length) return false;
  if (Date.parse(rows[0].expires_at) <= Date.now()) {
    await db.run('DELETE FROM admin_sessions WHERE token_hash = ?', [rows[0].token_hash]);
    return false;
  }
  return true;
}

