  function authText(key){ var pack=AUTH_I18N[state.locale]||AUTH_I18N.zh; return pack[key]||AUTH_I18N.zh[key]||key }
  function applyAuthLocale(){
    var lm=document.getElementById('login-modal');
    if(lm){
      var tabs=lm.querySelectorAll('[data-auth-tab]');
      if(tabs[0])tabs[0].textContent=authText('login');
      if(tabs[1])tabs[1].textContent=authText('register');
      var labels=lm.querySelectorAll('.auth-form label');
      if(labels[0])labels[0].textContent=authText('email');
      if(labels[1])labels[1].textContent=authText('password');
      if(labels[2])labels[2].textContent=authText('name');
      var emailInput=lm.querySelector('[name=email]'); if(emailInput)emailInput.placeholder=authText('phEmail');
      var pwdInput=lm.querySelector('[name=password]'); if(pwdInput)pwdInput.placeholder=authText('phPassword');
      var submit=lm.querySelector('#auth-submit'); if(submit)submit.textContent=authText(authMode==='register'?'submitRegister':'submitLogin');
      var err=lm.querySelector('#auth-error'); var code=err&&err.getAttribute('data-code'); if(err&&code)err.textContent=authText(code);
    }
    var am=document.getElementById('account-modal');
    if(am){
      var kicker=am.querySelector('.section-kicker'); if(kicker)kicker.textContent=authText('accountKicker');
      var title=am.querySelector('h3'); if(title)title.textContent=authText('accountTitle');
      var note=am.querySelector('#account-note'); if(note)note.textContent=authText('accountNote');
      var out=am.querySelector('#account-logout'); if(out)out.textContent=authText('logout');
    }
  }
  function setAuthMode(mode){
    authMode=mode==='register'?'register':'login';
    var lm=document.getElementById('login-modal'); if(!lm)return;
    lm.querySelectorAll('[data-auth-tab]').forEach(function(tab){ tab.classList.toggle('active',tab.getAttribute('data-auth-tab')===authMode) });
    var nameField=lm.querySelector('[data-auth-name]'); if(nameField)nameField.classList.toggle('hidden',authMode!=='register');
    var pwd=lm.querySelector('[name=password]'); if(pwd)pwd.setAttribute('autocomplete',authMode==='register'?'new-password':'current-password');
    var submit=lm.querySelector('#auth-submit'); if(submit)submit.textContent=authText(authMode==='register'?'submitRegister':'submitLogin');
    setAuthError('');
  }
  function setAuthError(code){ var el=document.getElementById('auth-error'); if(!el)return; el.setAttribute('data-code',code||''); el.textContent=code?authText(code):'' }
  function storeCustomer(data){
    state.customerToken=data.token;
    state.user={id:data.customer.id,email:data.customer.email,name:data.customer.name};
    localStorage.setItem('bamboo-customer-token',state.customerToken);
    localStorage.setItem('bamboo-user',JSON.stringify(state.user));
  }
  function finishCustomerAuth(data,toastKey){
    storeCustomer(data);
    closeModal('login-modal');
    renderRoute();
    toast(authText(toastKey));
  }
  function submitAuth(event){
    event.preventDefault();
    var form=event.target;
    var email=String(form.email.value||'').trim();
    var password=String(form.password.value||'');
    var name=form.name?String(form.name.value||'').trim():'';
    if(!email||!password){ setAuthError('errMissing'); return }
    if(!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)){ setAuthError('errInvalidEmail'); return }
    if(authMode==='register'&&password.length<8){ setAuthError('errWeakPassword'); return }
    var btn=document.getElementById('auth-submit'); if(btn)btn.disabled=true;
    var endpoint=authMode==='register'?'/api/auth/register':'/api/auth/login';
    api(endpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email:email,password:password,name:name})}).then(function(data){
      finishCustomerAuth(data,authMode==='register'?'registered':'loggedIn');
    }).catch(function(err){
      var map={email_taken:'errEmailTaken',invalid_credentials:'errCredentials',invalid_email:'errInvalidEmail',weak_password:'errWeakPassword'};
      setAuthError(map[err.code]||err.message||'errNetwork');
    }).finally(function(){ if(btn)btn.disabled=false });
  }
  function logoutCustomer(){
    if(state.customerToken){ fetch('/api/auth/logout',{method:'POST',headers:{'x-customer-token':state.customerToken}}).catch(function(){}) }
    state.customerToken=''; state.user=null;
    localStorage.removeItem('bamboo-customer-token');
    localStorage.removeItem('bamboo-user');
    closeModal('account-modal');
    renderRoute();
    toast(authText('loggedOut'));
  }
  function restoreCustomerSession(){
    if(!state.customerToken)return;
    var before=JSON.stringify(state.user||null);
    fetch('/api/auth/me',{headers:{'x-customer-token':state.customerToken}}).then(function(r){ if(!r.ok)throw new Error('unauthorized'); return r.json() }).then(function(data){
      if(!data||!data.customer)return;
      state.user={id:data.customer.id,email:data.customer.email,name:data.customer.name};
      localStorage.setItem('bamboo-user',JSON.stringify(state.user));
      if(JSON.stringify(state.user)!==before)renderRoute();
    }).catch(function(){
      state.customerToken=''; state.user=null;
      localStorage.removeItem('bamboo-customer-token');
      localStorage.removeItem('bamboo-user');
      if(before!=='null')renderRoute();
    });
  }
  function tr(key){ return (UI_TEXT[state.locale] && UI_TEXT[state.locale][key]) || (UI_EXTRA[state.locale] && UI_EXTRA[state.locale][key]) || UI_TEXT.en[key] || UI_EXTRA.en[key] || key; }
  function categoryText(category){ return tr(category==='家居'?'category_home':category==='收纳'?'category_storage':category==='餐厨'?'category_kitchen':category); }
